import{_ as e,o as r,c as t,ag as o}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"管理工程用户","description":"从工程用户预设创建页面登录账号、分配工程角色、重置密码，并区分组织账号与运行态身份。","frontmatter":{"title":"管理工程用户","description":"从工程用户预设创建页面登录账号、分配工程角色、重置密码，并区分组织账号与运行态身份。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/project-users.md","filePath":"zh/使用指南/管理工程用户.md"}'),i={name:"zh/guide/project-users.md"};function l(s,a,n,h,d,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="管理工程用户" tabindex="-1">管理工程用户 <a class="header-anchor" href="#管理工程用户" aria-label="Permalink to &quot;管理工程用户&quot;">​</a></h1><p>工程用户用于工程页面自己的登录，不是登录组织工作台的账号。本页维护<strong>工程的初始用户预设</strong>；正式运行的用户与策略需要随工程发布、更新安排同步，不要把预设保存当成所有部署立即生效。</p><p>修改预设需要工程创建者或组织管理员权限。其他成员看到只读提示时，请联系有权维护此工程的人，不要换用他人账号。</p><h2 id="_1-打开用户预设" tabindex="-1">1. 打开用户预设 <a class="header-anchor" href="#_1-打开用户预设" aria-label="Permalink to &quot;1. 打开用户预设&quot;">​</a></h2><ol><li>从公共入口登录组织，进入 <strong>“工程管理”</strong>。</li><li>找到目标工程，打开 <strong>“用户预设”</strong>。</li><li>核对对话框中的工程名称，选择 <strong>“用户管理”</strong>。</li></ol><p>不要转到组织的“用户管理”添加同名账号，那不会自动成为这个工程的页面用户。</p><h2 id="_2-准备角色并创建用户" tabindex="-1">2. 准备角色并创建用户 <a class="header-anchor" href="#_2-准备角色并创建用户" aria-label="Permalink to &quot;2. 准备角色并创建用户&quot;">​</a></h2><p>没有可选角色时，先按<a href="/induframe-docs/zh/guide/project-roles.html">管理工程角色</a>创建角色，再回来添加用户。</p><ol><li>点击 <strong>“创建用户”</strong>。</li><li>填写“登录账号”、显示名称和“初始密码”，按页面的工程密码要求准备口令。</li><li>选择该用户需要的角色，核对已选角色数量。</li><li>保存，等待“用户创建成功”。</li><li>回到列表搜索该账号，刷新或重新打开后确认资料与角色正确。</li></ol><p>按最小需要分配角色，不为了方便给所有人使用内置管理员。通过安全方式交付密码，不把口令放进普通文档或聊天群。</p><h2 id="_3-修改资料、角色和状态" tabindex="-1">3. 修改资料、角色和状态 <a class="header-anchor" href="#_3-修改资料、角色和状态" aria-label="Permalink to &quot;3. 修改资料、角色和状态&quot;">​</a></h2><p>使用用户行的“编辑”调整资料，使用 **“分配角色”**调整绑定。提交后核对角色列表，不把“创建了角色”当成已经分配给用户。</p><p>需要暂停使用时，先核对账号并通知使用者，再使用 <strong>“停用”</strong>；恢复时使用“启用”。当前页面编辑的是预设，正式运行中的会话和权限还需按部署更新安排验证。</p><p>内置 admin 用户受到保护，不允许停用或删除。不要通过删除角色、直接改文件等方法绕过保护。</p><h2 id="_4-忘记密码时" tabindex="-1">4. 忘记密码时 <a class="header-anchor" href="#_4-忘记密码时" aria-label="Permalink to &quot;4. 忘记密码时&quot;">​</a></h2><p>选择正确用户的 <strong>“重置密码”</strong>，输入新密码及确认新密码，满足当前工程密码要求后点击 <strong>“确认重置”</strong>。等待“密码重置成功”，再安全交付。</p><p>不要把组织管理员重置密码、工程用户重置密码和预览中的管理员口令设置混为一项操作。预览身份的用途见<a href="/induframe-docs/zh/guide/preview.html">页面预览</a>。</p><h2 id="_5-删除前确认" tabindex="-1">5. 删除前确认 <a class="header-anchor" href="#_5-删除前确认" aria-label="Permalink to &quot;5. 删除前确认&quot;">​</a></h2><p>删除用户会同步移除该用户的角色分配。先核对工程和账号，再阅读确认提示；不确定时取消。</p><p>需要停用而不是删除时，优先选择停用。不要假设删除后还能恢复，也不要把删除预设当成所有已发布版本的身份清理已经完成。</p><h2 id="怎样确认完成" tabindex="-1">怎样确认完成 <a class="header-anchor" href="#怎样确认完成" aria-label="Permalink to &quot;怎样确认完成&quot;">​</a></h2><p>重新读取列表，核对用户、角色和状态；用合适的工程用户检查开发预览，并在部署更新后另外验证正式页面登录。出现失败或结果不明确时，保留提示并先核对，避免重复创建。</p><p>下一步：<a href="/induframe-docs/zh/guide/project-roles.html">管理工程角色</a> · <a href="/induframe-docs/zh/guide/workspace-datapoints.html">配置数据点调用权限</a>。</p>',23)])])}const u=e(i,[["render",l]]);export{_ as __pageData,u as default};
